steps.code:
// Navigate to the provided URL
const base_url = 'https://news.ycombinator.com/';
const url = new URL(input.url || base_url);

navigate(url);


// Parse the current page to extract story URLs
const {urls} = parse();

// Handle pagination using URL-based approach
// The first page is at https://news.ycombinator.com/ (or ?p=1)
// Subsequent pages follow the pattern ?p=2, ?p=3, etc.
const max_page = input.max_page || 2;

// Only trigger pagination on the first run (not on reruns)
if (!input.is_rerun) {
    // Trigger rerun_stage for all pages from 2 to max_page
    for (let page = 2; page <= max_page; page++) {
        const next_page_url = new URL(base_url);
        next_page_url.searchParams.set('p', page.toString());
        rerun_stage({
            url: next_page_url.href,
            max_page: max_page,
            is_rerun: true
        });
    }
}

// Collect all URLs from the current page using next_stage
// IMPORTANT: Only collect Hacker News discussion URLs (item?id=...)
for (let story_url of urls) {
    next_stage({url: story_url});
}

parser.parser:
// Extract story URLs from the Hacker News homepage
// Stories are in <tr class="athing"> elements with unique IDs
// We need to extract the discussion URLs (item?id=...) instead of external links

const story_rows = $('tr.athing').toArray();

const urls = story_rows.map(row => {
    // Get the story ID from the tr element's id attribute
    const story_id = $(row).attr('id');

    if (story_id) {
        // Build the Hacker News discussion URL
        return `https://news.ycombinator.com/item?id=${story_id}`;
    }
    return null;
}).filter(Boolean); // Remove null values

console.log(`Found ${urls.length} story URLs on this page`);

return {urls};

