// Extract the story title
let title = $('.titleline a').text_sane();

// Extract the story URL
let url = $('.titleline a[href]').attr('href');
if (url) {
    url = new URL(url);
}

// Extract points from the score element
let points = null;
let scoreText = $('#score_49402189').text_sane() || $('.score').first().text_sane();
if (scoreText) {
    points = +scoreText.replace(/\D/g, '');
}

// Extract the author username
let author = $('.hnuser').first().text_sane();

// Extract comment count from the last link in subtext
let comment_count = null;
let commentText = $('.subtext a:last-child').text_sane();
if (commentText && commentText.includes('comment')) {
    comment_count = +commentText.replace(/\D/g, '');
}

return {
    title,
    url,
    points,
    author,
    comment_count
};

